import math

solutions = []
A_max = 6
B_max = 6

for a in range(A_max + 1):
    for b in range(B_max + 1):
        term = (2**a) * (5**b)
        N_squared = term + 625

        if N_squared >= 0:
            N = int(math.isqrt(N_squared))
            if N * N == N_squared:
                solutions.append((a, b, N))

print("Found solutions (a, b, N):")
for sol in solutions:
    print(sol)
